/**
 * Catalog-token helpers shared by the v2 builders.
 *
 * A reference embedded in an entity payload should be the **canonical token**
 * (`{ __kind, refName, name, parent? }`) and nothing more — just enough for
 * `resolvePayload` to swap it for an id at deploy. But the natural thing to pass
 * for an aspect ref is the barrel *root* object (`incidents`), which also
 * carries every bag (`automations`, `fields`, …). Embedding that verbatim bloats
 * the stored baseline and makes diffs unreadable. {@link slimTokens} walks a
 * payload and reduces every catalog token to its canonical fields, leaving
 * non-token values untouched.
 */
import { REF_SCOPE } from "./types.js";
/** True when `v` is a catalog ref token (`__kind ∈ REF_SCOPE` + a string refName). */
export function isCatalogToken(v) {
    if (typeof v !== "object" || v === null)
        return false;
    const rec = v;
    return (typeof rec.__kind === "string" &&
        rec.__kind in REF_SCOPE &&
        typeof rec.refName === "string");
}
/** Reduce a catalog token to its canonical fields (dropping barrel bags etc.). */
export function slimToken(token) {
    const out = {
        __kind: token.__kind,
        refName: token.refName,
    };
    if (typeof token.name === "string")
        out.name = token.name;
    if (token.parent !== undefined)
        out.parent = token.parent;
    if ((token.__kind === "app" || token.__kind === "element") && typeof token.namespace === "string") {
        out.namespace = token.namespace;
    }
    if ((token.parentKind === "app" || token.parentKind === "element"))
        out.parentKind = token.parentKind;
    if (typeof token.parentName === "string")
        out.parentName = token.parentName;
    if (typeof token.parentNamespace === "string")
        out.parentNamespace = token.parentNamespace;
    if ((token.__kind === "approvalChain" || token.__kind === "skill") && typeof token.unresolvedId === "string") {
        out.unresolvedId = token.unresolvedId;
    }
    if (token.__kind === "skill" && typeof token.parentName === "string")
        out.parentName = token.parentName;
    // The terraform path derives a field's resource type from its authoring
    // type — canonical field metadata, not a barrel bag.
    if (token.__kind === "field" && typeof token.fieldType === "string")
        out.fieldType = token.fieldType;
    // Same reasoning for a file reader: build needs to know which of the
    // excel/json/text/xml/ai resource types backs it to emit the right
    // `elementum_<type>_file_reader.<label>.id` reference - without this,
    // slimToken silently dropped readerType and automationToTf's
    // documentModel case threw "no recognized readerType" on every readFile
    // task build.
    if (token.__kind === "documentModel" && typeof token.readerType === "string")
        out.readerType = token.readerType;
    // Procedure lookup must carry the exact ordered Snowflake signature so the
    // provider can distinguish a procedure from a same-name UDF and select one
    // exact overload. This is identity metadata, not a barrel bag.
    if (token.__kind === "procedure" && Array.isArray(token.parameterTypes)) {
        out.parameterTypes = token.parameterTypes.filter((type) => typeof type === "string");
    }
    if (token.__kind === "procedure" && typeof token.databaseName === "string")
        out.databaseName = token.databaseName;
    if (token.__kind === "procedure" && typeof token.schemaName === "string")
        out.schemaName = token.schemaName;
    // Search-table resource selection is generated by catalog factories, not
    // authored as public API. Preserve the private discriminator so tool HCL
    // can reference the correct resource family.
    if (token.__kind === "searchTable" &&
        (token.__variant === "snowflake" || token.__variant === "linked" || token.__variant === "table")) {
        out.__variant = token.__variant;
    }
    if (token.__kind === "field" && Array.isArray(token.options)) {
        out.options = token.options.filter((option) => typeof option === "string");
    }
    if ((token.__kind === "field" || token.__kind === "tableColumn") && Array.isArray(token.tags)) {
        out.tags = token.tags.filter((tag) => typeof tag === "string");
    }
    else if ((token.__kind === "field" || token.__kind === "tableColumn") && Array.isArray(token.semanticTags)) {
        out.tags = token.semanticTags.filter((tag) => typeof tag === "string");
    }
    return out;
}
/**
 * Deep-walk `node`, replacing every catalog token with its slim canonical form.
 * Non-token objects/arrays are recursed; scalars pass through. Tokens are not
 * recursed into (their bags are dropped wholesale).
 */
export function slimTokens(node) {
    if (isCatalogToken(node))
        return slimToken(node);
    if (Array.isArray(node))
        return node.map(slimTokens);
    if (node !== null && typeof node === "object") {
        const out = {};
        for (const [k, v] of Object.entries(node))
            out[k] = slimTokens(v);
        return out;
    }
    return node;
}
